Dev7E_WriteWord:
	ld C,(XSP+0x06)                                      ; FE4C99  8f 06 23
	and C,0x07                                           ; FE4C9C  cb cc 07
	cp (XSP+0x04),0x00                                   ; FE4C9F  8f 04 3f 00
	jr nz, .LFE4CAA                                          ; FE4CA3  6e 05
	set 0x03,C                                           ; FE4CA5  cb 31 03
	jr .LFE4CAD                                              ; FE4CA8  68 03
.LFE4CAA:
