	pop C                                                ; FE4CB1  cb 05
	add XBC,0x007e0000                                   ; FE4CB3  e9 c8 00 00 7e 00
	ld WA,(XSP+0x08)                                     ; FE4CB9  9f 08 20
	ld (XBC),WA                                          ; FE4CBC  b1 50
	ret                                                  ; FE4CBE  0e
