	jr ule, .LFE5560                              ; FE5557  63 07
	ldw qiz, 0xffff                               ; FE5559  d7 fa 03 ff ff
	jr .LFE5567                                   ; FE555E  68 07
.LFE5560:
	cpw qiz, 0x80                                 ; FE5560  d7 fa cf 80 00
	jr z, .LFE553E                                ; FE5565  66 d7
.LFE5567:
	cp QIZ,0                                      ; FE5567  d7 fa d8
	jr z, .LFE5574                                ; FE556A  66 08
	pushw 0x01                                    ; FE556C  0b 01 00
	calr Fdc_SetError                                   ; FE556F  1e 12 09
