	cp HL,0xffff                                  ; FE55AA  db cf ff ff
	jr z, .LFE55B6                                ; FE55AE  66 06
	ld (Fdc_CurrentCylinder:24), 0xff                      ; FE55B0  f2 ee 5a 60 00 ff
.LFE55B6:
	cp	(0x605a12:24), 0xff                   ; FE55B6  c2 12 5a 60 3f ff
	jrl z, .LFE56D5                               ; FE55BC  76 16 01
	ld (0x605a12:24), 0xff                      ; FE55BF  f2 12 5a 60 00 ff
	pushw 0x80                                    ; FE55C5  0b 80 00
	calr Dev7B_WriteDsr_Shadowed                                   ; FE55C8  1e 00 ff
	pushw 0x02                                    ; FE55CB  0b 02 00
	calr Fdc_DelayTicks                                   ; FE55CE  1e 22 09
	inc 4,XSP                                     ; FE55D1  ef 64
	calr Fdc_RequestIsTrack0SectorProbe                                   ; FE55D3  1e 55 08
	cp HL,0xffff                                  ; FE55D6  db cf ff ff
	jr z, .LFE564A                                ; FE55DA  66 6e
	calr Fdc_RequestIsOp0WithCountFFFF                                   ; FE55DC  1e 89 08
	cp HL,0xffff                                  ; FE55DF  db cf ff ff
	jr z, .LFE564A                                ; FE55E3  66 65
	calr Fdc_ClearError                                   ; FE55E5  1e d0 08
	calr .LFE56D7                                 ; FE55E8  1e ec 00
	cp	(Fdc_ErrorCode:24), 0x00                   ; FE55EB  c2 15 5a 60 3f 00
	jrl nz, .LFE56CF                              ; FE55F1  7e db 00
.LFE55F4:
	calr Dev7B_ReadStatus                                   ; FE55F4  1e bf fe
	bit 0x07,L                                    ; FE55F7  cf 33 07
	jr z, .LFE55F4                                ; FE55FA  66 f8
	calr Dev7B_ReadStatus                                   ; FE55FC  1e b7 fe
