	ld A,(XBC)                                           ; FE75E3  81 21
	ld (XIX),A                                           ; FE75E5  b4 41
	sub XBC,XBC                                          ; FE75E7  e9 a1
	inc 1,XBC                                            ; FE75E9  e9 61
	add (xiz-4), xbc                                     ; FE75EB  ae fc 89
	add XIX,XBC                                          ; FE75EE  e9 84
	add HL,BC                                            ; FE75F0  d9 83
	cp HL,0x0020                                         ; FE75F2  db cf 20 00
	jr lt, .LFE75E0                                           ; FE75F6  61 e8
	jr .LFE7601                                              ; FE75F8  68 07
.LFE75FA:
	ld (XIX),0x00                                        ; FE75FA  b4 00 00
	inc 1,XIX                                            ; FE75FD  ec 61
	inc 1,HL                                             ; FE75FF  db 61
.LFE7601:
	cp HL,0x0200                                         ; FE7601  db cf 00 02
	jr lt, .LFE75FA                                           ; FE7605  61 f3
	lda xbc, (FatId_Floppy720K:24)                       ; FE7607  f2 d2 76 fe 31
	ld (xiz-4), xbc                                      ; FE760C  be fc 61
	ldw hl, 0x00                                         ; FE760F  33 00 00
.LFE7612:
