	ld A,(XBC)                                           ; FE7615  81 21
	ld (XIX),A                                           ; FE7617  b4 41
	sub XBC,XBC                                          ; FE7619  e9 a1
	inc 1,XBC                                            ; FE761B  e9 61
	add (xiz-4), xbc                                     ; FE761D  ae fc 89
	add XIX,XBC                                          ; FE7620  e9 84
	add HL,BC                                            ; FE7622  d9 83
	cp HL,0x0020                                         ; FE7624  db cf 20 00
